'use strict';

const crypto = require('crypto');

const db = require('../database');
const user = require('../user');

const utils = module.exports;

const tokenUtils = {};
utils.tokens = tokenUtils;
const tokenKey = token => `token:${token}`;
const finiteNumber = (value) => {
	if (value === null || value === undefined || value === '') {
		return null;
	}
	const number = Number(value);
	return Number.isFinite(number) ? number : null;
};

tokenUtils.list = async () => {
	const tokens = await db.getSortedSetRange('tokens:createtime', 0, -1);
	return await tokenUtils.get(tokens);
};

tokenUtils.get = async (tokens) => {
	if (tokens === null || tokens === undefined) {
		throw new Error('[[error:invalid-data]]');
	}
	const isArray = Array.isArray(tokens);
	const tokenList = isArray ? tokens : [tokens];
	if (!tokenList.length) {
		return [];
	}
	if (tokenList.some(token => typeof token !== 'string' || !token.length)) {
		throw new Error('[[error:invalid-data]]');
	}

	const [objects, lastSeen] = await Promise.all([
		db.getObjects(tokenList.map(tokenKey)),
		tokenUtils.getLastSeen(tokenList),
	]);
	const hydrated = tokenList.map((token, index) => {
		const data = objects[index];
		if (!data) {
			return null;
		}
		return {
			uid: finiteNumber(data.uid),
			description: data.description,
			timestamp: finiteNumber(data.timestamp),
			lastSeen: lastSeen[index],
		};
	});
	return isArray ? hydrated : hydrated[0];
};

tokenUtils.generate = async ({ uid, description } = {}) => {
	const numericUid = finiteNumber(uid);
	if (numericUid === null) {
		throw new Error('[[error:invalid-data]]');
	}
	if (numericUid !== 0 && !await user.exists(numericUid)) {
		throw new Error('[[error:no-user]]');
	}

	const token = crypto.randomBytes(32).toString('hex');
	const timestamp = Date.now();
	const tokenData = { uid: numericUid, timestamp };
	if (description !== undefined) {
		tokenData.description = description;
	}
	await Promise.all([
		db.setObject(tokenKey(token), tokenData),
		db.sortedSetAdd('tokens:createtime', timestamp, token),
		db.sortedSetAdd('tokens:uid', numericUid, token),
	]);
	return token;
};

tokenUtils.update = async (token, { description } = {}) => {
	if (typeof token !== 'string' || !token.length) {
		throw new Error('[[error:invalid-data]]');
	}
	await db.setObjectField(tokenKey(token), 'description', description);
	return await tokenUtils.get(token);
};

tokenUtils.delete = async (token) => {
	if (typeof token !== 'string' || !token.length) {
		throw new Error('[[error:invalid-data]]');
	}
	await Promise.all([
		db.delete(tokenKey(token)),
		db.sortedSetRemove('tokens:createtime', token),
		db.sortedSetRemove('tokens:uid', token),
		db.sortedSetRemove('tokens:lastSeen', token),
	]);
};

tokenUtils.log = async (token) => {
	if (typeof token !== 'string' || !token.length) {
		throw new Error('[[error:invalid-data]]');
	}
	await db.sortedSetAdd('tokens:lastSeen', Date.now(), token);
};

tokenUtils.getLastSeen = async (tokens) => {
	if (!Array.isArray(tokens)) {
		throw new Error('[[error:invalid-data]]');
	}
	if (!tokens.length) {
		return [];
	}
	const scores = await db.sortedSetScores('tokens:lastSeen', tokens);
	return tokens.map((token, index) => finiteNumber(scores[index]));
};

// Preserve the original internal entry points while exposing the cohesive API.
utils.log = tokenUtils.log;
utils.getLastSeen = tokenUtils.getLastSeen;
